-- BCIL Live: forms rebuilt from BCIL's Google Forms (31 Oct 2026). Safe to run more than once.
alter table public.forms add column if not exists description text;
insert into public.forms (slug, title, subtitle, description, sensitive, fields) values ($q$fcb27-registration$q$, $q$Finding Campus Balance 2027 Registration$q$, $q$6th edition · Saturday 23 January 2027 · Auditorium 900, UCC$q$, $q$Register for FCB 2027: digital safety, academic wellbeing, a campus life panel, and a CV and cover letter clinic. Join us in person or online.$q$, false, $j$[{"key": "full_name", "label": "Name (as you want it on the certificate)", "type": "text", "required": true}, {"key": "phone", "label": "Phone number (active WhatsApp number)", "type": "tel", "required": true}, {"key": "other_contact", "label": "Other contact", "type": "tel"}, {"key": "email", "label": "Email address", "type": "email", "required": true}, {"key": "level", "label": "Education level", "type": "select", "options": ["100", "200", "300", "400", "Postgraduate", "National Service Personnel", "Teaching Assistant", "Other"], "required": true}, {"key": "programme", "label": "What is your programme of study?", "type": "text", "required": true}, {"key": "mode", "label": "How will you be joining us?", "type": "radio", "options": ["In person", "Online"], "required": true}, {"key": "expectations", "label": "Expectations for the programme", "type": "textarea"}, {"key": "recommended_by", "label": "Who recommended you for this programme?", "type": "text"}, {"key": "certificate", "label": "Do you want a certificate for the programme?", "type": "radio", "options": ["Yes", "No"], "required": true, "help": "Save extra money by paying for your certificate now."}, {"key": "reference_name", "label": "Reference name", "type": "text", "help": "If you paid for a certificate, the name used for the payment."}]$j$::jsonb)
on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, description=excluded.description, fields=excluded.fields;
insert into public.forms (slug, title, subtitle, description, sensitive, fields) values ($q$fcb27-volunteer$q$, $q$FCB'27 Volunteering$q$, $q$Serve at Finding Campus Balance 2027$q$, $q$Team preference will be considered but is not guaranteed. Final assignments depend on event needs, volunteer numbers, skills and team capacity.$q$, false, $j$[{"key": "full_name", "label": "Full name", "type": "text", "required": true}, {"key": "email", "label": "Active email", "type": "email", "required": true}, {"key": "phone", "label": "Active phone / WhatsApp number", "type": "tel", "required": true}, {"key": "why", "label": "Why do you want to be a volunteer?", "type": "textarea", "required": true}, {"key": "team", "label": "Which FCB 2027 volunteer team would you prefer to join?", "type": "radio", "required": true, "options": ["Registration and Data", "Ushering & Participant Experience", "Protocol & Guest Relations", "Logistics & Venue Operations", "Media & Documentation", "Publicity & Communications"]}, {"key": "skills", "label": "What skills or experience could you contribute to FCB 2027?", "type": "checkbox", "required": true, "options": ["Communication/public speaking", "Registration/data management", "Event organization/logistics", "Guest relations/protocol", "Ushering/crowd coordination", "Social media/publicity", "Photography/videography", "Graphic design/content creation", "Leadership/team coordination", "Other"]}, {"key": "other_team", "label": "If your preferred team is full, are you willing to serve on another FCB 2027 team?", "type": "radio", "options": ["Yes", "No"], "required": true}, {"key": "training", "label": "Are you willing to take part in the required volunteer training and final event briefing/simulation?", "type": "radio", "options": ["Yes", "No"], "required": true}]$j$::jsonb)
on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, description=excluded.description, fields=excluded.fields;
insert into public.forms (slug, title, subtitle, description, sensitive, fields) values ($q$campus-sync-membership$q$, $q$Campus Sync UCC Membership$q$, $q$Join the BCIL Foundation club at the University of Cape Coast$q$, $q$Campus Sync is BCIL Foundation's campus club: skills, leadership, mentorship and service. Tell us about yourself.$q$, false, $j$[{"key": "full_name", "label": "Full (official) name", "type": "text", "required": true}, {"key": "email", "label": "Email address", "type": "email", "required": true}, {"key": "level", "label": "Current level", "type": "select", "options": ["100", "200", "300", "400", "Postgraduate", "National Service Personnel", "Teaching Assistant", "Other"], "required": true}, {"key": "programme", "label": "Programme of study", "type": "text", "required": true}, {"key": "student_id", "label": "Student ID number", "type": "text", "required": true}, {"key": "phone", "label": "Phone number", "type": "tel", "required": true}, {"key": "dob", "label": "Date of birth", "type": "date", "required": true}, {"key": "why", "label": "Why do you want to join the club, and what are your expectations?", "type": "textarea", "required": true}]$j$::jsonb)
on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, description=excluded.description, fields=excluded.fields;
insert into public.forms (slug, title, subtitle, description, sensitive, fields) values ($q$fcb27-mentorship$q$, $q$FCB 2027 Mentorship Registration$q$, $q$Be paired with a mentor for the year$q$, $q$FCB mentorship pairs students with experienced professionals, academics and recent graduates.$q$, false, $j$[{"key": "full_name", "label": "Full name", "type": "text", "required": true}, {"key": "email", "label": "Email address", "type": "email", "required": true}, {"key": "phone", "label": "Phone / WhatsApp number", "type": "tel", "required": true}, {"key": "level", "label": "Current level", "type": "select", "options": ["100", "200", "300", "400", "Postgraduate", "National Service Personnel", "Teaching Assistant", "Other"], "required": true}, {"key": "programme", "label": "Programme of study", "type": "text", "required": true}, {"key": "areas", "label": "Which areas do you want mentorship in?", "type": "checkbox", "required": true, "options": ["Academic performance", "Career and job search", "Leadership", "Personal development", "Finances", "Relationships and wellbeing", "Entrepreneurship", "Other"]}, {"key": "goals", "label": "What do you hope to achieve with a mentor this year?", "type": "textarea", "required": true}, {"key": "mode", "label": "How would you prefer to meet your mentor?", "type": "radio", "options": ["In person", "Online", "Either"], "required": true}]$j$::jsonb)
on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, description=excluded.description, fields=excluded.fields;
insert into public.forms (slug, title, subtitle, description, sensitive, fields) values ($q$cv-clinic$q$, $q$CV and Cover Letter Clinic$q$, $q$One-hour pre-programme session · CALC 10$q$, $q$Bring your CV and get one-on-one feedback before FCB 2027.$q$, false, $j$[{"key": "full_name", "label": "Full name", "type": "text", "required": true}, {"key": "email", "label": "Email address", "type": "email", "required": true}, {"key": "phone", "label": "Phone / WhatsApp number", "type": "tel", "required": true}, {"key": "level", "label": "Current level", "type": "select", "options": ["100", "200", "300", "400", "Postgraduate", "National Service Personnel", "Teaching Assistant", "Other"], "required": true}, {"key": "programme", "label": "Programme of study", "type": "text", "required": true}, {"key": "has_cv", "label": "Do you already have a CV?", "type": "radio", "options": ["Yes", "No, I need help starting one"], "required": true}, {"key": "applying_for", "label": "What are you applying for, or preparing for?", "type": "text", "required": true, "help": "For example: national service, internships, scholarships, a first job."}]$j$::jsonb)
on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, description=excluded.description, fields=excluded.fields;
insert into public.forms (slug, title, subtitle, description, sensitive, fields) values ($q$student-support-laptop$q$, $q$Student Support Initiative (laptop)$q$, $q$For deserving UCC undergraduates$q$, $q$Responses to this form are seen only by BCIL administrators.$q$, true, $j$[{"key": "full_name", "label": "Full name", "type": "text", "required": true}, {"key": "email", "label": "Email address", "type": "email", "required": true}, {"key": "phone", "label": "Phone / WhatsApp number", "type": "tel", "required": true}, {"key": "student_id", "label": "Student ID", "type": "text", "required": true}, {"key": "programme", "label": "Programme and level", "type": "text", "required": true}, {"key": "need", "label": "Why do you need a laptop, and how will it help your studies?", "type": "textarea", "required": true}]$j$::jsonb)
on conflict (slug) do update set title=excluded.title, subtitle=excluded.subtitle, description=excluded.description, fields=excluded.fields;
select slug, title, jsonb_array_length(fields) as questions from public.forms order by created_at;
